CREATE TABLE IF NOT EXISTS sys_sequence (id BIGINT PRIMARY KEY, seq_date DATETIME NOT NULL, current_val BIGINT NOT NULL DEFAULT 0, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, create_by BIGINT NOT NULL DEFAULT 0, update_by BIGINT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, UNIQUE KEY uk_sys_sequence_seq_date(seq_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sys_credential (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, credential_type VARCHAR(32) NOT NULL, secret_ref VARCHAR(255) NOT NULL DEFAULT '', verified TINYINT NOT NULL DEFAULT 0, status TINYINT NOT NULL DEFAULT 1, expires_at DATETIME NULL, pwd_update_time DATETIME NULL, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, create_by BIGINT NOT NULL DEFAULT 0, update_by BIGINT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, UNIQUE KEY uk_sys_credential_user_type(user_id,credential_type), KEY idx_sys_credential_user_id(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS oauth_client (id BIGINT PRIMARY KEY, client_id VARCHAR(64) NOT NULL, client_secret_hash VARCHAR(100) NULL, client_name VARCHAR(64) NOT NULL DEFAULT '', client_type VARCHAR(32) NOT NULL DEFAULT 'PUBLIC', client_auth_method VARCHAR(32) NOT NULL DEFAULT 'NONE', grant_types VARCHAR(255) NOT NULL, redirect_uris VARCHAR(1024) NOT NULL, scopes VARCHAR(255) NOT NULL DEFAULT 'openid,profile', require_pkce TINYINT NOT NULL DEFAULT 1, require_consent TINYINT NOT NULL DEFAULT 0, reuse_refresh_tokens TINYINT NOT NULL DEFAULT 0, access_token_ttl_sec INT NOT NULL DEFAULT 600, refresh_token_ttl_sec INT NOT NULL DEFAULT 604800, system_code VARCHAR(32) NOT NULL DEFAULT '', owner VARCHAR(64) NOT NULL DEFAULT '', env VARCHAR(16) NOT NULL DEFAULT '', enabled TINYINT NOT NULL DEFAULT 1, remark VARCHAR(255) NOT NULL DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, create_by BIGINT NOT NULL DEFAULT 0, update_by BIGINT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, UNIQUE KEY uk_oauth_client_client_id(client_id), KEY idx_oauth_client_enabled(enabled), KEY idx_oauth_client_system_code(system_code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS auth_grant (id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, client_id VARCHAR(64) NOT NULL, scopes VARCHAR(255) NOT NULL DEFAULT '', status TINYINT NOT NULL DEFAULT 1, revoked_at DATETIME NULL, revoke_reason VARCHAR(64) NOT NULL DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, create_by BIGINT NOT NULL DEFAULT 0, update_by BIGINT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, KEY idx_auth_grant_user_id(user_id), KEY idx_auth_grant_client_id(client_id), KEY idx_auth_grant_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempt (id BIGINT PRIMARY KEY, username VARCHAR(64) NOT NULL DEFAULT '', user_id BIGINT NULL, success TINYINT NOT NULL DEFAULT 0, fail_reason VARCHAR(64) NOT NULL DEFAULT '', ip VARCHAR(64) NOT NULL DEFAULT '', user_agent VARCHAR(255) NOT NULL DEFAULT '', client_id VARCHAR(64) NOT NULL DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, create_by BIGINT NOT NULL DEFAULT 0, update_by BIGINT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, KEY idx_login_attempt_username(username), KEY idx_login_attempt_ip(ip), KEY idx_login_attempt_create_time(create_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS auth_audit_log (id BIGINT PRIMARY KEY, action VARCHAR(64) NOT NULL, actor_user_id BIGINT NULL, target_type VARCHAR(32) NOT NULL DEFAULT '', target_id VARCHAR(64) NOT NULL DEFAULT '', detail VARCHAR(512) NOT NULL DEFAULT '', ip VARCHAR(64) NOT NULL DEFAULT '', create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, create_by BIGINT NOT NULL DEFAULT 0, update_by BIGINT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, KEY idx_auth_audit_log_action(action), KEY idx_auth_audit_log_create_time(create_time)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
